// @ts-nocheck — the generated copy lands in the work dir root, where Sentry's
// tsconfig (checkJs) would otherwise fail `pnpm run typecheck` on it.
/**
 * PM2 Ecosystem Configuration for Agent ${AGENT_ID}
 *
 * Auto-generated by `har env launch` — do not edit the generated copy.
 * Customize .har/ecosystem.agent.template.cjs to change processes.
 *
 * Sentry's `sentry devserver` normally runs rsbuild on the bind port and Django
 * on port+1. The harness splits that into two PM2 processes so each gets its
 * own allocated slot port:
 *   - web: Django only (`sentry devserver --no-watchers`) on API_PORT
 *   - ui:  rsbuild dev server on FE_PORT, proxying to Django on API_PORT
 * Agents and humans open http://localhost:FE_PORT.
 */

// The generated file and .env.agent.N live in the work dir root,
// so __dirname IS the work dir — repo root or the agent's git worktree.
const fs = require('fs');
const path = require('path');

const agentEnvPath = path.resolve(__dirname, '.env.agent.${AGENT_ID}');
const env = {};
try {
  for (const line of fs.readFileSync(agentEnvPath, 'utf8').split('\n')) {
    const m = line.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/);
    if (m && !line.trimStart().startsWith('#')) env[m[1]] = m[2].replace(/^["']|["']$/g, '');
  }
} catch {}

const venvBin = path.join(__dirname, '.venv', 'bin');

module.exports = {
  apps: [
    {
      name: 'har-${HARNESS_PROJECT_NAME}-agent-${AGENT_ID}-web',
      script: path.join(venvBin, 'sentry'),
      args: `devserver --no-watchers --no-workers 127.0.0.1:${env.API_PORT}`,
      interpreter: 'none',
      cwd: __dirname,
      env: {
        ...env,
        PATH: env.PATH || `${venvBin}:${process.env.PATH}`,
        // Templates load assets from the rsbuild dev server (FE_PORT).
        FORCE_WEBPACK_DEV_SERVER: '1',
        PYTHONUNBUFFERED: '1',
      },
      watch: false, // Django autoreload handles .py changes
      autorestart: true,
      kill_timeout: 10000,
      merge_logs: true,
      time: true,
    },
    {
      name: 'har-${HARNESS_PROJECT_NAME}-agent-${AGENT_ID}-ui',
      script: path.join(__dirname, 'node_modules', '.bin', 'rsbuild'),
      args: `dev --config=${path.join(__dirname, 'rsbuild.config.ts')}`,
      interpreter: 'none',
      cwd: __dirname,
      env: {
        ...env,
        PATH: env.PATH || `${venvBin}:${process.env.PATH}`,
        NODE_ENV: 'development',
        NODE_OPTIONS: '--max-old-space-size=4096',
        SENTRY_BACKEND_PORT: env.API_PORT,
        SENTRY_WEBPACK_PROXY_HOST: '127.0.0.1',
        SENTRY_WEBPACK_PROXY_PORT: '${FE_PORT}',
        // Agent-friendly asset mode: rsbuild.config.ts already disables the
        // error overlay (client.overlay=false) and HMR stays off unless
        // SENTRY_UI_HOT_RELOAD is set, so pages do full reloads on rebuild and
        // compile errors show up in `har env agent <id> logs ui`, not over the UI.
      },
      watch: false, // rsbuild's watcher handles static/ changes
      autorestart: true,
      kill_timeout: 5000,
      merge_logs: true,
      time: true,
    },
  ],
};
